window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-78ee3b57250f18d8"]={"versions": [{"id": "FIG-78ee3b57250f18d8", "releases": ["R2.1.20", "R3.0.7", "R3.1.5", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Protokoll- und Frame-Format-Diagramm (Bit-/Byte-Layout einer Protocol Data Unit). Das Diagramm spezifiziert den Aufbau des Protocol Control Information (PCI) Feldes eines Flow Control (FC) N-PDU/Frames innerhalb des AUTOSAR Classic Platform FlexRay Transport Layer (FrArTp). Es ordnet die Protokollsteuerungs-Parameter auf N-PDU-Ebene an der Schnittstelle zwischen Sender und Empfänger bei segmentierter Datenübertragung an.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Flow Control Frame besteht aus einem 3 Byte langen PCI-Header (<code>PCI (3 Byte)</code>), unterteilt in vier aufeinanderfolgende Felder:</p>\n<ul class=\"fig-list\">\n<li><code>FT (4 Bit)</code>: Frame Type (Kennzeichnung des N-PDU-Typs als Flow Control).</li>\n<li><code>FS (4 Bit)</code>: Flow Status (Statusanzeige zur Steuerung des weiteren Sendeflusses, z. B. Continue To Send, Wait, Overflow).</li>\n<li><code>BS (8 Bit)</code>: Block Size (maximale Anzahl aufeinanderfolgender Consecutive Frames, die ohne weitere Flow-Control-Bestätigung übertragen werden dürfen).</li>\n<li><code>STmin (8 Bit)</code>: Separation Time minimum (minimal einzuhaltender zeitlicher Abstand zwischen zwei aufeinanderfolgenden Consecutive Frames).</li>\n</ul>\n<p class=\"fig-p\">Eine Nutzlast (Payload) ist im Flow-Control-Frame nicht enthalten; die gesamte PDU besteht aus diesen 3 Byte PCI.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Empfänger einer segmentierten Übertragung generiert und sendet das Flow Control Frame nach dem Empfang eines First Frame (FF) oder nach Ablauf eines definierten Übertragungsblocks (Block Size). Anhand des Feldes <code>FS</code> signalisiert der Empfänger dem Sender seine Empfangsbereitschaft. Über <code>BS</code> wird dem Sender vorgegeben, wie viele Consecutive Frames gesendet werden dürfen, bevor ein erneutes FC-Frame erwartet wird. <code>STmin</code> definiert die minimale Pause zwischen den einzelnen Consecutive Frames, um eine Überlastung des Empfängerpuffers zu verhindern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Bit- und Byte-Aufteilung für die Implementierung des FrArTp-Moduls gemäß ISO 10681-2 bzw. AUTOSAR-Transportschichtspezifikation. Entwickler müssen sicherstellen, dass die Felder <code>FT</code> und <code>FS</code> im ersten Byte exakt jeweils 4 Bit belegen (<code>FT</code> höherwertiges Nibble, <code>FS</code> niederwertiges Nibble), gefolgt von <code>BS</code> in Byte 1 und <code>STmin</code> in Byte 2. Sender- und Empfängerzustandsautomaten müssen die Wertebereiche von <code>FS</code> (CTS/WT/OVFLW), <code>BS</code> und <code>STmin</code> korrekt serialisieren, deserialisieren und timerbasiert anwenden.</p>"}, {"id": "FIG-664db45648b2a976", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Protokoll- und Frame-Format-Diagramm (Bit-/Byte-Layout einer Protocol Data Unit). Das Diagramm spezifiziert den Aufbau des Protocol Control Information (PCI) Feldes eines Flow Control (FC) N-PDU/Frames innerhalb des AUTOSAR Classic Platform FlexRay Transport Layer (FrArTp). Es ordnet die Protokollsteuerungs-Parameter auf N-PDU-Ebene an der Schnittstelle zwischen Sender und Empfänger bei segmentierter Datenübertragung an.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Flow Control Frame besteht aus einem 3 Byte langen PCI-Header (<code>PCI (3 Byte)</code>), unterteilt in vier aufeinanderfolgende Felder:</p>\n<ul class=\"fig-list\">\n<li><code>FT (4 Bit)</code>: Frame Type (Kennzeichnung des N-PDU-Typs als Flow Control).</li>\n<li><code>FS (4 Bit)</code>: Flow Status (Statusanzeige zur Steuerung des weiteren Sendeflusses, z. B. Continue To Send, Wait, Overflow).</li>\n<li><code>BS (8 Bit)</code>: Block Size (maximale Anzahl aufeinanderfolgender Consecutive Frames, die ohne weitere Flow-Control-Bestätigung übertragen werden dürfen).</li>\n<li><code>STmin (8 Bit)</code>: Separation Time minimum (minimal einzuhaltender zeitlicher Abstand zwischen zwei aufeinanderfolgenden Consecutive Frames).</li>\n</ul>\n<p class=\"fig-p\">Eine Nutzlast (Payload) ist im Flow-Control-Frame nicht enthalten; die gesamte PDU besteht aus diesen 3 Byte PCI.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Empfänger einer segmentierten Übertragung generiert und sendet das Flow Control Frame nach dem Empfang eines First Frame (FF) oder nach Ablauf eines definierten Übertragungsblocks (Block Size). Anhand des Feldes <code>FS</code> signalisiert der Empfänger dem Sender seine Empfangsbereitschaft. Über <code>BS</code> wird dem Sender vorgegeben, wie viele Consecutive Frames gesendet werden dürfen, bevor ein erneutes FC-Frame erwartet wird. <code>STmin</code> definiert die minimale Pause zwischen den einzelnen Consecutive Frames, um eine Überlastung des Empfängerpuffers zu verhindern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Bit- und Byte-Aufteilung für die Implementierung des FrArTp-Moduls gemäß ISO 10681-2 bzw. AUTOSAR-Transportschichtspezifikation. Entwickler müssen sicherstellen, dass die Felder <code>FT</code> und <code>FS</code> im ersten Byte exakt jeweils 4 Bit belegen (<code>FT</code> höherwertiges Nibble, <code>FS</code> niederwertiges Nibble), gefolgt von <code>BS</code> in Byte 1 und <code>STmin</code> in Byte 2. Sender- und Empfängerzustandsautomaten müssen die Wertebereiche von <code>FS</code> (CTS/WT/OVFLW), <code>BS</code> und <code>STmin</code> korrekt serialisieren, deserialisieren und timerbasiert anwenden.</p>"}], "trans": [{"from": "FIG-78ee3b57250f18d8", "to": "FIG-664db45648b2a976", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-664db45648b2a976", "to": "FIG-78ee3b57250f18d8", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
